const sheets = $json.sheets || [];
const idOf = (t) => { const s = sheets.find(x => x.properties.title === t); return s ? s.properties.sheetId : null; };

const DARK = {red:0.12,green:0.16,blue:0.22};
const WHITE = {red:1,green:1,blue:1};
const requests = [];

const styleTab = (title, widths) => {
  const sid = idOf(title);
  if (sid === null) return;
  requests.push({updateSheetProperties:{properties:{sheetId:sid,gridProperties:{frozenRowCount:1}},fields:'gridProperties.frozenRowCount'}});
  requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{backgroundColor:DARK,horizontalAlignment:'LEFT',verticalAlignment:'MIDDLE',wrapStrategy:'WRAP',textFormat:{foregroundColor:WHITE,bold:true,fontSize:11}}},fields:'userEnteredFormat(backgroundColor,horizontalAlignment,verticalAlignment,wrapStrategy,textFormat)'}});
  requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:200},cell:{userEnteredFormat:{verticalAlignment:'TOP',wrapStrategy:'WRAP',textFormat:{fontSize:10}}},fields:'userEnteredFormat(verticalAlignment,wrapStrategy,textFormat)'}});
  widths.forEach((w,i) => {
    requests.push({updateDimensionProperties:{range:{sheetId:sid,dimension:'COLUMNS',startIndex:i,endIndex:i+1},properties:{pixelSize:w},fields:'pixelSize'}});
  });
  requests.push({addBanding:{bandedRange:{range:{sheetId:sid,startRowIndex:1,endRowIndex:200},rowProperties:{firstBandColor:{red:1,green:1,blue:1},secondBandColor:{red:0.97,green:0.97,blue:0.98}}}}});
};

styleTab('Fun & Immersive Ideas',[250,520,120,190,270,110]);
styleTab('War Plan',[150,470,90,120,115,300]);
styleTab('Anna - Confirmed',[150,240,560,270]);

const funId = idOf('Fun & Immersive Ideas');
if (funId !== null) {
  requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:funId,startRowIndex:1,endRowIndex:200,startColumnIndex:5,endColumnIndex:6}],booleanRule:{condition:{type:'TEXT_CONTAINS',values:[{userEnteredValue:'DO IT'}]},format:{backgroundColor:{red:0.82,green:0.94,blue:0.85},textFormat:{bold:true,foregroundColor:{red:0.04,green:0.35,blue:0.18}}}}},index:0}});
  requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:funId,startRowIndex:1,endRowIndex:200,startColumnIndex:5,endColumnIndex:6}],booleanRule:{condition:{type:'TEXT_CONTAINS',values:[{userEnteredValue:'MAYBE'}]},format:{backgroundColor:{red:1,green:0.95,blue:0.8},textFormat:{bold:true,foregroundColor:{red:0.48,green:0.33,blue:0.02}}}}},index:0}});
}

const warId = idOf('War Plan');
if (warId !== null) {
  const ownerRule = (name,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:warId,startRowIndex:1,endRowIndex:200,startColumnIndex:2,endColumnIndex:3}],booleanRule:{condition:{type:'TEXT_EQ',values:[{userEnteredValue:name}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
  requests.push(ownerRule('Krish',{red:0.85,green:0.91,blue:0.99},{red:0.06,green:0.27,blue:0.56}));
  requests.push(ownerRule('Loz',{red:0.99,green:0.89,blue:0.94},{red:0.6,green:0.09,blue:0.33}));
  requests.push(ownerRule('Both',{red:0.88,green:0.89,blue:0.99},{red:0.2,green:0.19,blue:0.6}));
  requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:warId,startRowIndex:1,endRowIndex:200,startColumnIndex:4,endColumnIndex:5}],booleanRule:{condition:{type:'TEXT_EQ',values:[{userEnteredValue:'Done'}]},format:{backgroundColor:{red:0.82,green:0.94,blue:0.85},textFormat:{bold:true,foregroundColor:{red:0.04,green:0.35,blue:0.18}}}}},index:0}});
  requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:warId,startRowIndex:1,endRowIndex:200,startColumnIndex:1,endColumnIndex:2}],booleanRule:{condition:{type:'TEXT_CONTAINS',values:[{userEnteredValue:'HARD DEADLINE'}]},format:{backgroundColor:{red:1,green:0.87,blue:0.87},textFormat:{bold:true,foregroundColor:{red:0.6,green:0.11,blue:0.11}}}}},index:0}});
  requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:warId,startRowIndex:1,endRowIndex:200,startColumnIndex:0,endColumnIndex:1}],booleanRule:{condition:{type:'TEXT_CONTAINS',values:[{userEnteredValue:'EVENT WEEK'}]},format:{backgroundColor:{red:0.99,green:0.91,blue:0.8},textFormat:{bold:true}}}},index:0}});
}

const annaId = idOf('Anna - Confirmed');
if (annaId !== null) {
  requests.push({repeatCell:{range:{sheetId:annaId,startRowIndex:1,endRowIndex:200,startColumnIndex:0,endColumnIndex:1},cell:{userEnteredFormat:{textFormat:{bold:true,fontSize:10}}},fields:'userEnteredFormat.textFormat'}});
  requests.push({addConditionalFormatRule:{rule:{ranges:[{sheetId:annaId,startRowIndex:1,endRowIndex:200,startColumnIndex:0,endColumnIndex:1}],booleanRule:{condition:{type:'TEXT_CONTAINS',values:[{userEnteredValue:'DEADLINE'}]},format:{backgroundColor:{red:1,green:0.87,blue:0.87},textFormat:{bold:true,foregroundColor:{red:0.6,green:0.11,blue:0.11}}}}},index:0}});
}

['Actions & Negotiation','Scenario Planner','Archive','Post-4pm Continuation','Namaste Info'].forEach(t => {
  const sid = idOf(t);
  if (sid !== null) requests.push({updateSheetProperties:{properties:{sheetId:sid,hidden:true},fields:'hidden'}});
});

['Dashboard','War Plan','Guest List','Fun & Immersive Ideas','Anna - Confirmed','Cost Model'].forEach((t,i) => {
  const sid = idOf(t);
  if (sid !== null) requests.push({updateSheetProperties:{properties:{sheetId:sid,index:i},fields:'index'}});
});

return [{json:{requests}}];
